:root {
  --bg: #1a1a19;
  --card: #242422;
  --text: #f0efec;
  --muted: #8d8c84;
  --accent: #3987e5;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, sans-serif;
}
.card {
  text-align: center;
  padding: 48px 64px;
  border-radius: 24px;
  background: var(--card);
}
.label { color: var(--muted); letter-spacing: 0.2em; text-transform: uppercase; }
#time { font-size: 96px; margin: 8px 0 32px; font-variant-numeric: tabular-nums; }
.controls { display: flex; gap: 16px; justify-content: center; }
button {
  font: inherit;
  font-size: 20px;
  padding: 12px 32px;
  border-radius: 999px;
  border: 2px solid var(--accent);
  background: var(--accent);
  color: white;
  cursor: pointer;
}
button.ghost { background: transparent; color: var(--text); }
